<script setup lang="ts">
import { useCmsI18n } from '@/composables/useCmsI18n';
import { computed, onBeforeUnmount, ref, watch } from 'vue';
import { cmsApi } from '../api';
import type { ConfigurationField, ConfigurationType, Locale, SiteConfiguration } from '../types';
import ConfigurationValue from './ConfigurationValue.vue';
import ConfigurationModelEditor from './ConfigurationModelEditor.vue';
import { configurationChild, configurationDefault, configurationPresets, scalarConfigurationTypes } from './configurationModel';
const { t } = useCmsI18n();
const props=defineProps<{siteId:string;locales:Locale[];can:(code:string)=>boolean}>();
const fields=ref<ConfigurationField[]>([]),values=ref<Record<string,any>>({}),overrides=ref<Record<string,any>>({}),effective=ref<Record<string,any>>({}),selectedLocale=ref(''),busy=ref(false),saving=ref(false),error=ref(''),success=ref(''),activeGroup=ref('');
const dialog=ref(false),editingKey=ref(''),optionsText=ref(''),fieldForm=ref<ConfigurationField>({key:'',label:'',type:'text',group:t('cms.labels.basicSettings'),localized:false,default:'',options:[]});
const types=computed<Array<{value:ConfigurationType;label:string}>>(()=>[...scalarConfigurationTypes,{value:'list',label:t('cms.labels.listConfigurationModel')}]);
const groups=computed(()=>[...new Set(fields.value.filter(f=>!selectedLocale.value||f.localized).map(f=>f.group))]);
const shownFields=computed(()=>fields.value.filter(f=>f.group===activeGroup.value&&(!selectedLocale.value||f.localized)));
watch(groups,next=>{if(!next.includes(activeGroup.value))activeGroup.value=next[0]||'';},{immediate:true});
const canSave=computed(()=>props.can(selectedLocale.value?'cms:site:locale':'cms:site:edit'));
let generation=0;
const clone=<T,>(v:T):T=>JSON.parse(JSON.stringify(v));
function apply(data:SiteConfiguration){fields.value=clone(data.fields);values.value=clone(data.values);overrides.value=clone(data.overrides);effective.value=clone(data.effective);if(activeGroup.value&&!groups.value.includes(activeGroup.value))activeGroup.value='';}
async function load(){const token=++generation;error.value='';success.value='';fields.value=[];values.value={};overrides.value={};effective.value={};if(!props.can('cms:site:detail'))return;busy.value=true;try{const data=await cmsApi.configuration(props.siteId,selectedLocale.value||undefined);if(token===generation)apply(data);}catch{if(token===generation)error.value=t('cms.labels.couldNotLoadSiteSettingsRefreshAndRetry');}finally{if(token===generation)busy.value=false;}}
async function persist(payload:Record<string,any>){const token=generation,target=props.siteId;if(saving.value)return;saving.value=true;error.value='';success.value='';try{const data=await cmsApi.saveConfiguration({site_id:target,...payload});if(token===generation&&props.siteId===target){apply(data);dialog.value=false;success.value=t('cms.labels.settingsSaved');}}catch{if(token===generation)error.value=t('cms.labels.saveFailedCheckFieldTypesRequiredValuesAndSite');}finally{saving.value=false;}}
async function save(){if(!props.can(selectedLocale.value?'cms:site:locale':'cms:site:edit')||busy.value)return;await persist(selectedLocale.value?{locale:selectedLocale.value,values:clone(overrides.value)}:{values:clone(values.value)});}
function templateCode(field:ConfigurationField){return field.type==='list'?'{cms:config name="'+field.key+'" as="item"}…{/cms:config}':'{$config.'+field.key+'}';}
function inherited(field:ConfigurationField){return !Object.prototype.hasOwnProperty.call(overrides.value,field.key);}
function setOverride(field:ConfigurationField,enabled:boolean){if(!props.can('cms:site:locale'))return;if(enabled)overrides.value[field.key]=clone(baseValue(field));else delete overrides.value[field.key];}
function baseValue(field:ConfigurationField){return Object.prototype.hasOwnProperty.call(values.value,field.key)?values.value[field.key]:field.default;}
function value(field:ConfigurationField){return selectedLocale.value&&!inherited(field)?overrides.value[field.key]:baseValue(field);}
function update(field:ConfigurationField,next:any){if(!props.can(selectedLocale.value?'cms:site:locale':'cms:site:edit'))return;if(selectedLocale.value)overrides.value[field.key]=next;else values.value[field.key]=next;}
function openField(field?:ConfigurationField){if(!props.can('cms:site:edit')||selectedLocale.value)return;editingKey.value=field?.key||'';fieldForm.value=field?clone(field):{key:'',label:'',type:'text',group:activeGroup.value||t('cms.labels.basicSettings'),localized:false,default:'',options:[]};optionsText.value=(field?.options||[]).join('\n');dialog.value=true;}
function openPreset(key:string){
 if(!props.can('cms:site:edit')||selectedLocale.value)return;
 const preset=configurationPresets.find(item=>item.key===key);if(!preset)return;
 const existing=fields.value.find(field=>field.key===key);openField(existing);
 if(!existing)fieldForm.value={key,label:preset.label,type:'list',group:preset.label,localized:true,default:[],fields:preset.fields(),options:[]};
}
const protectedTypes:Record<string,ConfigurationType>={logo:'image',favicon:'image',contact_url:'url',icp_url:'url',email:'email'};
watch(()=>fieldForm.value.key,key=>{const type=protectedTypes[key];if(type&&fieldForm.value.type!==type){fieldForm.value.type=type;changeType();}});
function changeType(){fieldForm.value.default=configurationDefault(fieldForm.value.type);if(fieldForm.value.type==='list'&&!fieldForm.value.fields?.length)fieldForm.value.fields=[configurationChild('name',t('cms.labels.name2'))];}
async function saveField(){
 if(!props.can('cms:site:edit')||selectedLocale.value)return;const field=clone(fieldForm.value);field.options=field.type==='select'?optionsText.value.split('\n').map(v=>v.trim()).filter(Boolean):[];
 if(!/^[a-z][a-z0-9_]{0,63}$/.test(field.key)||['constructor','prototype'].includes(field.key)||!field.label.trim()||!field.group.trim()){error.value=t('cms.labels.enterAValidCodeNameAndGroupCodesMust');return;}
 if(!editingKey.value&&fields.value.some(f=>f.key===field.key)){error.value=t('cms.labels.configurationCodeAlreadyExists');return;}
 if(field.type==='list'){
  const children=field.fields||[],keys=children.map(child=>child.key);
  if(!children.length||children.length>20||new Set(keys).size!==keys.length||children.some(child=>!/^[a-z][a-z0-9_]{0,63}$/.test(child.key)||['enabled','constructor','prototype'].includes(child.key)||!child.label.trim()||!scalarConfigurationTypes.some(type=>type.value===child.type))){error.value=t('cms.labels.configurationModelsRequire1To20FieldsWithValid');return;}
 }
 const next=editingKey.value?fields.value.map(f=>f.key===editingKey.value?field:f):[...fields.value,field];await persist({fields:next,values:clone(values.value)});
}
async function removeField(field:ConfigurationField){if(!props.can('cms:site:edit')||selectedLocale.value)return;const next=fields.value.filter(f=>f.key!==field.key),nextValues=clone(values.value);delete nextValues[field.key];await persist({fields:next,values:nextValues});}
watch(()=>props.siteId,()=>{selectedLocale.value='';void load();},{immediate:true});watch(selectedLocale,()=>{void load();});onBeforeUnmount(()=>{generation++;});
</script>
<template><section class="configuration-panel" v-loading="busy">
 <div class="configuration-heading"><div><h3>{{ t('cms.labels.websiteSettings') }}</h3><p>{{ t('cms.labels.publicWebsiteSettingsAreIndependentPerSiteAddFields') }}</p></div><div v-if="!selectedLocale&&can('cms:site:edit')" class="configuration-add-actions"><el-dropdown @command="openPreset"><el-button>{{ t('cms.labels.addCommonList') }}</el-button><template #dropdown><el-dropdown-menu><el-dropdown-item v-for="preset in configurationPresets" :key="preset.key" :command="preset.key">{{ preset.label }}</el-dropdown-item></el-dropdown-menu></template></el-dropdown><el-button @click="openField()">{{ t('cms.labels.addSetting') }}</el-button></div></div>
 <el-alert v-if="error" :title="error" type="error" :closable="false" /><el-alert v-if="success" :title="success" type="success" :closable="false" />
 <div class="configuration-filters"><el-select v-model="selectedLocale" :aria-label="t('cms.labels.configurationLanguage')" :disabled="saving"><el-option value="" :label="t('cms.labels.siteDefaults')" /><el-option v-for="locale in locales" :key="locale.locale" :value="locale.locale" :label="`${locale.name} (${locale.locale})`" /></el-select><el-tag v-if="selectedLocale" type="info">{{ t('cms.labels.onlyShowSettingsWithLanguageOverrides') }}</el-tag></div>
 <el-tabs v-if="groups.length" v-model="activeGroup" class="configuration-groups" :aria-label="t('cms.labels.configurationGroup')"><el-tab-pane v-for="group in groups" :key="group" :name="group" :label="group" /></el-tabs>
 <el-form label-position="top" class="configuration-fields"><div v-for="field in shownFields" :key="field.key" class="configuration-field" :class="{'is-list':field.type==='list'}"><div class="field-heading"><label>{{ field.label }}<small>{{ field.group }} · {{ field.key }}</small></label><div v-if="!selectedLocale&&can('cms:site:edit')" class="field-actions"><el-button link type="primary" @click="openField(field)">{{ t('cms.labels.edit') }}</el-button><el-popconfirm :title="t('cms.labels.removeThisSettingAndAllItsLanguageOverridesThis')" @confirm="removeField(field)"><template #reference><el-button link type="danger">{{ t('cms.labels.remove') }}</el-button></template></el-popconfirm></div><el-switch v-if="selectedLocale" :model-value="!inherited(field)" :disabled="!canSave||saving" :active-text="t('cms.labels.override')" :inactive-text="t('cms.labels.inherit')" @change="setOverride(field,!!$event)" /></div><ConfigurationValue :field="field" :model-value="value(field)" :disabled="!canSave||saving||!!selectedLocale&&inherited(field)" @update:model-value="update(field,$event)" /><code class="field-template">{{ templateCode(field) }}</code></div></el-form>
 <el-empty v-if="!shownFields.length&&!busy&&!error" :description="t('cms.labels.noSettingsInThisGroupAddSettingsInSite')" />
 <div class="configuration-footer"><el-button v-if="canSave" type="primary" :loading="saving" :disabled="busy" @click="save">{{ selectedLocale?t('cms.labels.saveLanguageSettings'):t('cms.labels.saveSiteSettings') }}</el-button><span v-else class="readonly-hint">{{ t('cms.labels.yourRoleHasReadAccessOnly') }}</span></div>
 <el-dialog v-model="dialog" :title="editingKey?t('cms.labels.editSetting'):t('cms.labels.addSetting')" :width="fieldForm.type==='list'?'min(920px,96vw)':'min(650px,94vw)'" :close-on-click-modal="false"><el-alert v-if="error" :title="error" type="error" :closable="false" /><el-form label-position="top"><el-form-item :label="t('cms.labels.settingName')" required><el-input v-model="fieldForm.label" maxlength="80" :placeholder="t('cms.labels.eGCustomerServiceWechat')" /></el-form-item><el-form-item :label="t('cms.labels.settingCode')" required><el-input v-model="fieldForm.key" :disabled="!!editingKey" maxlength="64" :placeholder="t('cms.labels.eGServiceWechat')" /></el-form-item><div class="definition-row"><el-form-item :label="t('cms.labels.group')" required><el-input v-model="fieldForm.group" maxlength="40" :placeholder="t('cms.labels.enterAnExistingOrNewGroupName')" /></el-form-item><el-form-item :label="t('cms.labels.type')"><el-select v-model="fieldForm.type" :disabled="!!protectedTypes[fieldForm.key]" @change="changeType"><el-option v-for="type in types" :key="type.value" :label="type.label" :value="type.value" /></el-select></el-form-item></div><el-form-item v-if="fieldForm.type==='select'" :label="t('cms.labels.optionsOnePerLine')"><el-input v-model="optionsText" type="textarea" :rows="4" /></el-form-item><el-form-item v-if="fieldForm.type==='list'" :label="t('cms.labels.configurationModelFieldsPerRecord')"><ConfigurationModelEditor :model-value="fieldForm.fields||[]" @update:model-value="fieldForm.fields=$event" /></el-form-item><el-form-item v-else :label="t('cms.labels.defaultValue')"><ConfigurationValue :field="{...fieldForm,options:optionsText.split('\n').map(v=>v.trim()).filter(Boolean)}" v-model="fieldForm.default" /></el-form-item><el-form-item :label="t('cms.labels.allowDifferentValuesPerLanguage')"><el-switch v-model="fieldForm.localized" /></el-form-item><el-alert :title="t('cms.labels.whenChangingTypesExistingValuesAndTranslationsMustMatch')" type="info" :closable="false" /></el-form><template #footer><el-button @click="dialog=false">{{ t('cms.labels.cancel') }}</el-button><el-button v-if="can('cms:site:edit')" type="primary" :loading="saving" @click="saveField">{{ t('cms.labels.saveSetting') }}</el-button></template></el-dialog>
</section></template>
<style scoped>.configuration-panel{margin-top:30px;padding-top:25px;border-top:1px solid var(--el-border-color-lighter)}.configuration-heading{display:flex;justify-content:space-between;align-items:center;gap:20px}.configuration-add-actions{display:flex;gap:10px;flex-wrap:wrap;flex:none}.configuration-heading h3{margin:0;font-size:16px}.configuration-heading p{font-size:12px;color:var(--el-text-color-secondary);margin:8px 0 0}.configuration-filters{display:flex;gap:12px;align-items:center;flex-wrap:wrap;margin:22px 0}.configuration-filters .el-select{width:220px}.configuration-fields{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:24px 30px}.configuration-field{min-width:0}.configuration-field.is-list{grid-column:1/-1}.field-heading{display:flex;align-items:flex-start;justify-content:space-between;gap:15px;margin-bottom:10px;font-size:13px}.field-heading small{display:block;font-size:11px;color:var(--el-text-color-secondary);margin-top:4px}.field-actions{display:flex;align-items:center;flex:none}.field-template{display:block;margin-top:7px;font-size:11px;color:var(--el-text-color-placeholder)}.configuration-footer{display:flex;justify-content:flex-end;margin-top:25px}.readonly-hint{font-size:12px;color:var(--el-text-color-secondary)}.definition-row{display:grid;grid-template-columns:1fr 1fr;gap:20px}.configuration-panel>.el-alert{margin-top:18px}@media(max-width:800px){.configuration-fields{grid-template-columns:1fr}.configuration-heading{align-items:flex-start}.configuration-heading p{line-height:1.8}.configuration-filters .el-select{width:100%}.definition-row{grid-template-columns:1fr;gap:0}}
</style>
